sheet({title:'Stinger', units:'in'})

// Robots must fit inside the 18 x 18 x 18 box during initialization: 
// corner at x=0, y=0, z=0; 18 along x, 18 along y, 18 tall
box(-9,-9,0, 18,18,18, {fill:C.white, alpha:0.15, limit:true})

// Variables
const W=17, L=17.5          // frame outside width (x) and length (y)
const T=2.76, H=4.5, Z0=1  // rail thickness, rail height, bottom of the rails above the tiles


                          // Chassis
// Frame
for (const x of [-8.06, 5.11]){
  box(x, -L/2, 0,  T, L, H, {fill:C.alu}) // rails start at the front edge
}
// Dimensioning
dim([-8.06,-L/2,H], [-8.06, L/2,H], {off:40, text:`${L}" Chassis length`})
dim([-8.06,-L/2,H], [-5.3, -L/2,H], {off:40, text:`${T}" Chassis width`})

// Cross Frame Support Dimensioning 
for (const y of [-0.945, 6]){
  box(-5.3, y, 1.81, 10.39, 1.89, 0.47, {fill: C.alu}) // back and middle horizontal frame to hold the vertical frames together
}
dim([-5.3,6,2.28],[5.09,6,2.28],{off:40})               // prints 10.39
leader([0,6,2.28],'cross member 1.89 × 0.47, 2×',60,-50)


// Wheels
for (const x of [-7.43, 5.74]){ // -8.06+0.63 and 5.11+0.63: wheel starts 0.63 in from each pod's left face
  for (const y of [-6.61, 6.61]){ // 8.5-1.89: axle so the tread ends flush with the pod ends
    cyl(x, y, 2.05, 2.05, 1.5, {axis: 'x', fill: C.dark})
  }
}
// Wheels Dimensioning
dim([-7.43,-6.61,0],[-7.43,-6.61,4.1],{off:-40})        // diameter, prints 4.10
dim([-7.43,-6.61,2.05],[-5.93,-6.61,2.05],{off:40})     // width, prints 1.50
leader([-7.43,-6.61,4.1],'104 mm mecanum, 4×',-60,-40)


                          // Intake

// Ramp
let fl = box(-5.3, -L/2, 0.3, 10.40, 7.04, 0.125, {fill:C.blue})
fl.rot[0] = 15

// Dimensioning
dim([-5.3,-L/2,0.3],[5.1,-L/2,0.3],{off:50})

leader([0,-5,1.2], '16° ramp', 60, -40)

// Guides
let gl = box(-5.0,  -L/2, 0.425,  0.125, 6, 1.5, {fill:C.alu, part: fl})
let gr = box(4.875, -L/2, 0.425,  0.125, 6, 1.5, {fill:C.alu, part: fl})
gl.rot[2] = -25
gr.rot[2] =  25

// Dimensioning
dim([-2.35,-3.5,1.8],[2.34,-3.5,1.8],{off:-40})     // throat, prints ≈4.69
